def image(page,xref,alt,cls=''):
    return f'<img class="{cls}" src="/profile/page-{page:02d}-{xref}.webp" alt="{alt}" loading="lazy">'
def portfolio_logos(i,page,xref,client):
    if i==1: logos=image(6,1223,'Royal Commission')+'<img src="/profile/page-06-sabic.webp" alt="SABIC" loading="lazy">'
    elif i==2: logos=image(6,1223,'Royal Commission')+image(page,xref,client)
    elif i==3: logos=image(page,xref,client)+image(6,1433,'Transgaz')
    else: logos=image(page,xref,client)
    return '<div class="project-logos">'+logos+'</div>'
def label(num,title):return f'<div class="section-kicker reveal"><span>{num}</span><p>{title}</p></div>'
